-- Reorders the base duas collection so "دعائي لوالديّ معًا" (parents) is
-- first — which the app pins as the leading card on the home screen's
-- "duas" shelf — and expands its list from 4 duas to 14.
update public.duas_base
set content = '[{"id": "parents", "title": "دعائي لوالديّ معًا", "icon": "👨‍👩‍👦", "duas": ["رب ارحمهما كما ربياني صغيرا", "ربنا اغفر لي ولوالديّ وللمؤمنين يوم يقوم الحساب", "رب أوزعني أن أشكر نعمتك التي أنعمت عليّ وعلى والديّ وأن أعمل صالحًا ترضاه", "اللهم ارضَ عنهما كما رضيا عنّي صغيرا، وأكرمهما كما أكرماني", "اللهم أطل عمرهما على طاعتك، وارزقهما الصحة والعافية، وبارك لهما في أيامهما", "اللهم اغفر لهما ذنوبهما، وارفع درجتهما، وأكرم نزلهما", "اللهم اجزهما عني خير ما جزى والدًا عن ولده، فلقد ربياني صغيرًا وتعبا عليّ كثيرًا", "اللهم اجمعنا بهما في الفردوس الأعلى من الجنة، مع النبيين والصديقين والشهداء والصالحين", "اللهم لا تحرمني برّهما، ووفقني لطاعتهما فيما يرضيك، واجعلني سببًا في راحة قلبيهما", "اللهم اجعل عملي هذا خالصًا لوجهك، واجعل ثوابه في ميزان حسناتهما", "اللهم إن كانا حيَّين فأطل أعمارهما على طاعتك، وإن كانا قد توفّيا فارحمهما رحمة واسعة واغفر لهما وأدخلهما فسيح جناتك", "اللهم اجعلني بارًّا بوالديّ في حياتهما وبعد مماتهما، ولا تجعلني من العاقين", "اللهم ارزقني رضاهما، فإن رضاك في رضاهما", "اللهم أعنّي على برّهما وطاعتهما، ولا تجعل بيني وبينهما إلا كل خير"]}, {"id": "self", "title": "دعائي لنفسي", "icon": "🧕", "duas": ["اللهم اجعلني ممن يذكرك كثيرًا ويشكرك كثيرًا ويخشاك كثيرًا ويطيعك كثيرًا", "اللهم إني أسألك الهدى والتقى والعفاف والغنى", "اللهم أصلح لي ديني الذي هو عصمة أمري، وأصلح لي دنياي التي فيها معاشي، وأصلح لي آخرتي التي فيها معادي", "رب اشرح لي صدري ويسر لي أمري", "اللهم رحمتك أرجو فلا تكلني إلى نفسي طرفة عين، وأصلح لي شأني كله، لا إله إلا أنت", "اللهم ثبّتني على دينك حتى ألقاك وأنت راضٍ عني", "اللهم اجعل خير عمري آخره، وخير عملي خواتمه، وخير أيامي يوم ألقاك"]}, {"id": "wife", "title": "دعائي لزوجتي", "icon": "💞", "duas": ["ربنا هب لنا من أزواجنا وذرياتنا قرة أعين واجعلنا للمتقين إماما", "اللهم ألّف بين قلبينا، واجعل بيننا مودة ورحمة دائمة", "اللهم اجعلها قرة عين لي، وأعنّي على أن أكون خير رفيق لها", "اللهم رب الناس أذهب البأس، اشف أنت الشافي، لا شفاء إلا شفاؤك، شفاءً لا يغادر سقما", "اللهم احفظ سعادتنا وبيتنا، وارزقنا التفاهم والرضا فيما بيننا"]}, {"id": "children", "title": "دعائي لأولادي", "icon": "🧒", "duas": ["رب هب لي من الصالحين", "رب اجعلني مقيم الصلاة ومن ذريتي ربنا وتقبل دعاء", "ربنا هب لنا من أزواجنا وذرياتنا قرة أعين واجعلنا للمتقين إماما", "أعيذكما بكلمات الله التامة من كل شيطان وهامة، ومن كل عين لامّة", "اللهم اجعلهم من الهداة المهتدين، غير الضالين ولا المضلين", "اللهم بارك لي في أولادي ولا تسلبني إياهم، وأرني فيهم قرة عيني قبل موتي", "اللهم اجعلهم قرة عين لي في الدنيا والآخرة، ووفقهم لما تحب وترضى"]}, {"id": "mother", "title": "دعائي لأمي", "icon": "🤱", "duas": ["رب ارحمهما كما ربياني صغيرا", "ربنا اغفر لي ولوالديّ وللمؤمنين يوم يقوم الحساب", "اللهم أطل عمرها على طاعتك، وارزقها الصحة والعافية", "اللهم اغفر لها ذنوبها، وارفع درجتها، وأكرم نزلها", "اللهم اجعل الفردوس الأعلى مثواها، وأثبها عني خير الجزاء"]}, {"id": "father", "title": "دعائي لأبي", "icon": "🧔", "duas": ["رب ارحمهما كما ربياني صغيرا", "ربنا اغفر لي ولوالديّ وللمؤمنين يوم يقوم الحساب", "اللهم ارزقه القوة والعافية، وبارك له في عمره وعمله", "اللهم سدّد خطاه، وأعنه على أمور دينه ودنياه", "اللهم اجزه عني خير ما جزيت والدًا عن ولده"]}, {"id": "family", "title": "دعائي للأهل والأقارب", "icon": "🏡", "duas": ["رب اغفر لي ولوالديّ ولمن دخل بيتي مؤمنا وللمؤمنين والمؤمنات", "اللهم صِل من وصلني منهم، واجعلني سببًا في تآلف قلوبهم واجتماع شملهم", "اللهم اشفِ مريضهم، وفرّج همّهم، وارزقهم من فضلك ما يغنيهم"]}, {"id": "friends", "title": "دعائي للأصدقاء والأحبة", "icon": "🤝", "duas": ["اللهم اجزهم عني خيرًا على كل معروف قدّموه لي", "اللهم بارك لهم فيما رزقتهم، واجمعنا وإياهم في مقعد صدق عندك", "اللهم أدم بيننا المحبة والوفاء، واجعلنا عونًا لبعضنا على الخير"]}, {"id": "ummah", "title": "دعائي لعموم المسلمين والمستضعفين", "icon": "🕋", "duas": ["ربنا أخرجنا من هذه القرية الظالم أهلها واجعل لنا من لدنك وليا واجعل لنا من لدنك نصيرا", "ربنا اغفر لنا ولإخواننا الذين سبقونا بالإيمان ولا تجعل في قلوبنا غلا للذين آمنوا ربنا إنك رءوف رحيم", "اللهم انصر المستضعفين من المسلمين في كل مكان، وفرّج كربهم، واجمع شملهم"]}, {"id": "reassurance", "title": "الطمأنينة عند الخوف والفزع والقلق", "icon": "🕊️", "duas": ["ربنا أفرغ علينا صبرا وثبت أقدامنا وانصرنا على القوم الكافرين", "ربنا لا تزغ قلوبنا بعد إذ هديتنا وهب لنا من لدنك رحمة إنك أنت الوهاب", "حسبنا الله ونعم الوكيل", "اللهم إني أعوذ بك من الهم والحزن، ومن العجز والكسل، ومن الجبن والبخل"]}, {"id": "relief", "title": "الفرج من الهم والحزن والضيق", "icon": "🌤️", "duas": ["لا إله إلا الله العظيم الحليم، لا إله إلا الله رب العرش العظيم، لا إله إلا الله رب السماوات ورب الأرض ورب العرش الكريم", "لا إله إلا أنت سبحانك إني كنت من الظالمين", "اللهم لا سهل إلا ما جعلته سهلا، وأنت تجعل الحزن إذا شئت سهلا"]}, {"id": "trust", "title": "التوكل وحسن الظن بالله والرضا", "icon": "🤲", "duas": ["ومن يتوكل على الله فهو حسبه إن الله بالغ أمره", "حسبي الله لا إله إلا هو عليه توكلت وهو رب العرش العظيم", "اللهم ارزقني الرضا بقضائك، والصبر على بلائك، وحسن الظن بك في كل حال"]}, {"id": "protection", "title": "الحفظ من الفتن والحسد والعين", "icon": "🛡️", "duas": ["اللهم إني أعوذ بك من الفتن ما ظهر منها وما بطن", "ربنا لا تجعلنا فتنة للذين كفروا واغفر لنا ربنا إنك أنت العزيز الحكيم", "أعوذ بكلمات الله التامات من شر ما خلق", "أعوذ بك من فتنة المحيا والممات"]}, {"id": "provision", "title": "الرزق والمال والبركة", "icon": "💰", "duas": ["رب إني لما أنزلت إلي من خير فقير", "اللهم اكفني بحلالك عن حرامك، وأغنني بفضلك عمن سواك", "اللهم بارك لي فيما رزقتني، واخلف عليّ كل ما أنفقت في سبيلك", "اللهم إني أعوذ بك من الفقر، وأعوذ بك من قلة، ومن ذلة"]}, {"id": "work", "title": "العمل والتجارة والتوفيق", "icon": "💼", "duas": ["اللهم إني أسألك علما نافعا ورزقا طيبا وعملا متقبلا", "اللهم افتح لي أبواب الخير والرزق من حيث أحتسب ومن حيث لا أحتسب", "رب يسّر ولا تعسّر، وتمم بالخير"]}, {"id": "knowledge", "title": "العلم والفهم والحفظ", "icon": "📚", "duas": ["رب زدني علما", "اللهم لا سهل إلا ما جعلته سهلا، وأنت تجعل الحزن إذا شئت سهلا", "اللهم علّمني ما ينفعني، وانفعني بما علمتني، وزدني علما"]}, {"id": "health", "title": "الصحة والشفاء", "icon": "💊", "duas": ["اللهم رب الناس أذهب البأس، اشف أنت الشافي، لا شفاء إلا شفاؤك، شفاءً لا يغادر سقما", "اللهم عافني في بدني، اللهم عافني في سمعي، اللهم عافني في بصري", "اللهم إني أسألك العافية في الدنيا والآخرة"]}, {"id": "forgiveness", "title": "المغفرة والتوبة والاستغفار", "icon": "🌙", "duas": ["ربنا ظلمنا أنفسنا وإن لم تغفر لنا وترحمنا لنكونن من الخاسرين", "رب اغفر وارحم وأنت خير الراحمين", "أستغفر الله العظيم الذي لا إله إلا هو الحي القيوم وأتوب إليه", "سيد الاستغفار كاملًا موجود في أذكار الصباح"]}, {"id": "husn-khatima", "title": "حسن الخاتمة", "icon": "✨", "duas": ["اللهم اجعل خير عمري آخره، وخير عملي خواتمه، وخير أيامي يوم ألقاك", "اللهم إني أسألك الثبات عند الشهادتين عند الموت، ونطق الحق عند الرضا والغضب", "اللهم توفني مسلمًا وألحقني بالصالحين"]}, {"id": "jannah-najah", "title": "العتق من النار ودخول الجنة", "icon": "🌿", "duas": ["اللهم أجرني من النار", "اللهم إني أسألك الجنة وما قرب إليها من قول أو عمل، وأعوذ بك من النار وما قرب إليها من قول أو عمل", "ربنا آتنا في الدنيا حسنة وفي الآخرة حسنة وقنا عذاب النار"]}, {"id": "jawami", "title": "جوامع الدعاء (خير الدنيا والآخرة)", "icon": "🌸", "duas": ["ربنا آتنا في الدنيا حسنة وفي الآخرة حسنة وقنا عذاب النار", "اللهم إني أسألك من الخير كله عاجله وآجله، ما علمت منه وما لم أعلم، وأعوذ بك من الشر كله عاجله وآجله، ما علمت منه وما لم أعلم", "اللهم اجعل لي من كل هم فرجا، ومن كل ضيق مخرجا، وارزقني من حيث لا أحتسب"]}, {"id": "jumuah", "title": "أدعية يوم الجمعة", "icon": "🕌", "duas": ["أكثِر من الصلاة على النبي ﷺ يوم الجمعة وليلتها", "تحرّ ساعة الإجابة في آخر ساعة من عصر يوم الجمعة بالدعاء", "اللهم اجعل جمعتنا هذه مباركة، واغفر لنا فيها، وارحمنا"]}, {"id": "ramadan", "title": "أدعية رمضان وليلة القدر", "icon": "🌙", "duas": ["اللهم إنك عفو تحب العفو فاعف عني", "اللهم بلغنا رمضان، وأعنّا فيه على صيامه وقيامه", "اللهم اجعلنا فيه من عتقائك من النار", "اللهم اقبل صيامنا وقيامنا، وتقبل منا صالح الأعمال"]}]',
    updated_at = now()
where id = 1;
